"""Captura a cauda de erro original, incluindo ANSI e separadores Unicode."""
import argparse,ast,json,re,subprocess,types
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--reference',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();commit='8552d4f3d';tree=ast.parse(subprocess.check_output(['git','-C',str(a.reference),'show',f'{commit}:backend/app/atualizar.py'],text=True));nodes=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in ['_cauda','_motivo_da_falha']];ns={'_MARCA_FALHA':'##HANGAR-FALHA##','subprocess':subprocess,'_ANSI':re.compile(r'\x1b\[[0-9;]*[a-zA-Z]')};exec(compile(ast.Module(body=nodes,type_ignores=[]),'<original-tail>','exec'),ns);rows=[]
